"use client";

import type { ReactNode } from "react";
import Link from "next/link";
import { usePathname } from "next/navigation";
import { TopBar } from "./TopBar";

type AppShellProps = { children: ReactNode };

export function AppShell({ children }: AppShellProps) {
  const pathname = usePathname();
  const isActive = (path: string) => pathname === path;

  return (
    <div className="app-shell">
      <aside className="sidebar d-none d-lg-flex flex-column">
        <div className="brand-mark mb-5">
          <Link
            className={`nav-link ${isActive("/") ? "active" : ""}`}
            href="/"
          >
            <span className="brand-icon">p</span>
            <span>
              pomo<span className="text-primary">flow</span>
            </span>
          </Link>
        </div>
        <nav className="nav flex-column gap-2" aria-label="Navegação principal">
          <Link
            className={`nav-link ${isActive("/home") ? "active" : ""}`}
            href="/home"
          >
            <i className="bi bi-house-door-fill" aria-hidden="true" /> Home
          </Link>
          <Link
            className={`nav-link ${isActive("/") ? "active" : ""}`}
            href="/"
          >
            <i className="bi bi-house-door-fill" aria-hidden="true" /> Visão geral
          </Link>
          <Link
            className={`nav-link ${isActive("/sessions") ? "active" : ""}`}
            href="/sessions"
          >
            <i className="bi bi-hourglass-split" aria-hidden="true" /> Sessões
          </Link>
          <Link
            className={`nav-link ${isActive("/tasks") ? "active" : ""}`}
            href="/tasks"
          >
            <i className="bi bi-list-check" aria-hidden="true" /> Tarefas
          </Link>
          <Link
            className={`nav-link ${isActive("/insights") ? "active" : ""}`}
            href="/insights"
          >
            <i className="bi bi-graph-up-arrow" aria-hidden="true" /> Insights
          </Link>
        </nav>
        <div className="sidebar-footer mt-auto">
          <Link
            className={`nav-link ${isActive("/settings") ? "active" : ""}`}
            href="/settings"
          >
            <i className="bi bi-gear-fill" aria-hidden="true" /> Preferências
          </Link>
          <div className="user-chip mt-4">
            <div className="avatar">AM</div>
            <div>
              <strong>Alex Martins</strong>
              <small>Plano pessoal</small>
            </div>
          </div>
        </div>
      </aside>
      <main className="main-content">
        <TopBar />
        {children}
      </main>
    </div>
  );
}
