"use client";

import { useState, useEffect } from "react";

type Tarefa = {
  id: number;
  nome: string;
  status: "a fazer" | "pendente" | "concluida";
};

const statusDisponiveis: Tarefa["status"][] = [
  "a fazer",
  "pendente",
  "concluida",
];

export default function FormularioTasks() {
  const [input, setInput] = useState("");
  const [tarefas, setTarefas] = useState<Tarefa[]>([]);
  const [status, setStatus] = useState<Tarefa["status"]>("a fazer");
  const [tarefasCarregadas, setTarefasCarregadas] = useState(false);

  useEffect(() => {
    const tarefasSalvas = localStorage.getItem("@Tarefas");

    if (tarefasSalvas) {
      try {
        const tarefasParseadas: unknown = JSON.parse(tarefasSalvas);

        if (Array.isArray(tarefasParseadas)) {
          setTarefas(tarefasParseadas);
        }
      } catch {
        localStorage.removeItem("@Tarefas");
      }
    }
    setTarefasCarregadas(true);
  }, []);

  useEffect(() => {
    if (!tarefasCarregadas) return;

    localStorage.setItem("@Tarefas", JSON.stringify(tarefas));
  }, [tarefas, tarefasCarregadas]);

  const handleSubmit = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();

    const nome = input.trim();
    if (!nome) return;

    setTarefas((tarefasAtuais) => [
      ...tarefasAtuais,
      { id: Date.now(), nome, status },
    ]);
    setInput("");
  };

  return (
    <>
      <div className="row">
        <div className="col-md-6">
          <div className="card bg-white mb-3">
            <div className="card-body">
              <h3>Formulário de Tarefas</h3>
              <form onSubmit={handleSubmit}>
                <div className="mb-3">
                  <input
                    className="form-control"
                    type="text"
                    placeholder="Digite uma tarefa"
                    aria-label="default input example"
                    required
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                  />
                </div>

                <div className="mb-3">
                  <label htmlFor="status-inicial" className="form-label">
                    Status inicial
                  </label>
                  <select
                    id="status-inicial"
                    className="form-select"
                    value={status}
                    onChange={(e) =>
                      setStatus(e.target.value as Tarefa["status"])
                    }
                  >
                    {statusDisponiveis.map((statusDisponivel) => (
                      <option key={statusDisponivel} value={statusDisponivel}>
                        {statusDisponivel === "a fazer"
                          ? "A Fazer"
                          : statusDisponivel === "concluida"
                            ? "Concluída"
                            : "Pendente"}
                      </option>
                    ))}
                  </select>
                </div>

                <div>
                  <button type="submit" className="btn btn-primary">
                    Enviar
                  </button>
                </div>
              </form>
            </div>
          </div>
        </div>
      </div>
      <div className="mt-3">
        <div className="d-flex flex-column gap-2">
          {tarefas.length === 0 ? (
            <p className="text-muted">Nenhuma tarefa cadastrada.</p>
          ) : (
            tarefas.map((tarefa) => (
              <div className="card" key={tarefa.id}>
                <div className="card-body">
                  <p className="card-text">ID: {tarefa.id}</p>
                  <p className="card-title">Tarefa: {tarefa.nome}</p>
                  <p className="card-text">Status: {tarefa.status}</p>
                </div>
              </div>
            ))
          )}
        </div>
      </div>
    </>
  );
}
